position:relative; height:150px;
                                                    border:1px dashed #ccc; border-radius:4px;
                                                    background:#fafafa; cursor:crosshair;

height:120px; border:1px dashed #ccc;
                                                    border-radius:4px; display:flex;
                                                    align-items:center; justify-content:center;
                                                    color:#bbb; font-size:13px;

t.script:
(function () {
    "use strict";

    // ── State ────────────────────────────────────────────
    var currentTab  = "draw";
    var hasDrawn    = false;
    var autoSel     = null;   // selected auto-style index
    var loadedImage = null;   // data-url from file upload

    var btn     = document.getElementById("jiv_submit_btn");
    var sigData = document.getElementById("jiv_sig_data");
    var consent = document.getElementById("jiv_consent");
    var nameEl  = document.getElementById("jiv_signer_name");

    // ── Tabs ─────────────────────────────────────────────
    document.querySelectorAll(".jiv-sig-tab").forEach(function (t) {
        t.addEventListener("click", function () {
            var tab = t.getAttribute("data-tab");
            currentTab = tab;
            document.querySelectorAll(".jiv-sig-tab").forEach(function (x) {
                x.style.borderBottom = "2px solid transparent";
                x.style.fontWeight   = "normal";
            });
            t.style.borderBottom = "2px solid #875A7B";
            t.style.fontWeight   = "600";
            document.querySelectorAll(".jiv-tab-pane").forEach(function (p) {
                p.style.display = "none";
            });
            document.getElementById("jiv-tab-" + tab).style.display = "";
            if (tab === "auto") buildAutoStyles();
            updateBtn();
        });
    });

    // ── DRAW tab ─────────────────────────────────────────
    var canvas  = document.getElementById("jiv_sig_canvas");
    var pad     = document.getElementById("jiv_draw_pad");
    var hint    = document.getElementById("jiv_draw_hint");
    var ctx     = canvas.getContext("2d");
    var drawing = false;

    function resizeCanvas() {
        var r = pad.getBoundingClientRect();
        var img = ctx.getImageData(0, 0, canvas.width, canvas.height);
        canvas.width  = r.width;
        canvas.height = r.height;
        ctx.lineWidth   = 2.5;
        ctx.lineCap     = "round";
        ctx.lineJoin    = "round";
        ctx.strokeStyle = "#1a1a1a";
        if (hasDrawn) ctx.putImageData(img, 0, 0);
    }
    resizeCanvas();
    window.addEventListener("resize", resizeCanvas);

    function getPos(e) {
        var r = canvas.getBoundingClientRect();
        var s = e.touches ? e.touches[0] : e;
        return { x: s.clientX - r.left, y: s.clientY - r.top };
    }
    canvas.addEventListener("mousedown", function (e) {
        drawing = true;
        var p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y);
    });
    canvas.addEventListener("mousemove", function (e) {
        if (!drawing) return;
        var p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke();
        if (!hasDrawn) { hasDrawn = true; hint.style.display = "none"; }
        updateBtn();
    });
    canvas.addEventListener("mouseup",    function () { drawing = false; });
    canvas.addEventListener("mouseleave", function () { drawing = false; });
    canvas.addEventListener("touchstart", function (e) {
        e.preventDefault(); drawing = true;
        var p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y);
    }, { passive: false });
    canvas.addEventListener("touchmove", function (e) {
        e.preventDefault(); if (!drawing) return;
        var p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke();
        if (!hasDrawn) { hasDrawn = true; hint.style.display = "none"; }
        updateBtn();
    }, { passive: false });
    canvas.addEventListener("touchend", function () { drawing = false; });

    document.getElementById("jiv_draw_clear").addEventListener("click", function () {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hasDrawn = false; hint.style.display = "";
        updateBtn();
    });

    // ── AUTO tab ─────────────────────────────────────────
    var FONTS = [
        { label: "Style 1", font: "italic 38px Georgia, serif" },
        { label: "Style 2", font: "italic 36px 'Palatino Linotype', serif" },
        { label: "Style 3", font: "36px 'Brush Script MT', cursive" },
        { label: "Style 4", font: "italic bold 32px 'Times New Roman', serif" },
    ];
    var autoBuilt = false;

    function buildAutoStyles() {
        if (autoBuilt) return;
        autoBuilt = true;
        var container = document.getElementById("jiv_auto_styles");
        var name = nameEl.value || "Your Name";
        FONTS.forEach(function (f, i) {
            var c = document.createElement("canvas");
            c.width = 220; c.height = 80;
            var cx = c.getContext("2d");
            cx.clearRect(0, 0, 220, 80);
            cx.font = f.font;
            cx.fillStyle = "#1a1a1a";
            cx.textBaseline = "middle";
            cx.fillText(name, 10, 42);
            // underline
            var w = Math.min(cx.measureText(name).width + 10, 210);
            cx.beginPath(); cx.moveTo(10, 62); cx.lineTo(w, 62);
            cx.strokeStyle = "#1a1a1a"; cx.lineWidth = 1; cx.stroke();

            var wrap = document.createElement("div");
            wrap.style.cssText = "border:2px solid #dee2e6; border-radius:6px;" +
                "cursor:pointer; overflow:hidden; background:#fff;";
            wrap.appendChild(c);
            wrap.addEventListener("click", function () {
                document.querySelectorAll("#jiv_auto_styles div").forEach(
                    function (w2) { w2.style.borderColor = "#dee2e6"; });
                wrap.style.borderColor = "#875A7B";
                autoSel = i;
                updateBtn();
            });
            container.appendChild(wrap);
        });

        // Rebuild when name changes
        nameEl.addEventListener("input", function () {
            autoBuilt = false;
            container.innerHTML = "";
            autoSel = null;
            buildAutoStyles();
            updateBtn();
        });
    }

    // ── LOAD tab ─────────────────────────────────────────
    document.getElementById("jiv_load_file").addEventListener("change", function (e) {
        var file = e.target.files[0];
        if (!file) return;
        var reader = new FileReader();
        reader.onload = function (ev) {
            loadedImage = ev.target.result;
            var prev = document.getElementById("jiv_load_preview");
            prev.innerHTML = "";
            var img = document.createElement("img");
            img.src = loadedImage;
            img.style.cssText = "max-height:110px; max-width:100%; object-fit:contain;";
            prev.appendChild(img);
            updateBtn();
        };
        reader.readAsDataURL(file);
    });

    // ── Validation + submit ──────────────────────────────
    consent.addEventListener("change", updateBtn);

    function isReady() {
        if (!consent.checked) return false;
        if (currentTab === "draw")  return hasDrawn;
        if (currentTab === "auto")  return autoSel !== null;
        if (currentTab === "load")  return loadedImage !== null;
        return false;
    }

    function updateBtn() {
        btn.disabled = !isReady();
    }

    document.getElementById("jiv_sign_form").addEventListener("submit", function () {
        if (currentTab === "draw") {
            sigData.value = canvas.toDataURL("image/png");
        } else if (currentTab === "auto") {
            // render selected auto style to a canvas
            var ac = document.createElement("canvas");
            ac.width = 400; ac.height = 100;
            var acx = ac.getContext("2d");
            var f = FONTS[autoSel];
            acx.font = f.font;
            acx.fillStyle = "#1a1a1a";
            acx.textBaseline = "middle";
            acx.fillText(nameEl.value || "Signature", 10, 50);
            var tw = Math.min(acx.measureText(nameEl.value || "Signature").width + 10, 390);
            acx.beginPath(); acx.moveTo(10, 78); acx.lineTo(tw, 78);
            acx.strokeStyle = "#1a1a1a"; acx.lineWidth = 1.5; acx.stroke();
            sigData.value = ac.toDataURL("image/png");
        } else if (currentTab === "load") {
            sigData.value = loadedImage;
        }
    });

})();
